using StackExchange.Redis;

public class RateLimiter
{
    private readonly IDatabase _db;

    public RateLimiter(IConnectionMultiplexer redis)
    {
        _db = redis.GetDatabase();
    }

    public async Task<bool> IsAllowedAsync(string clientId, int limit, TimeSpan window)
    {
        var now = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
        var previousKey = $"rate:{clientId}:{now - (long)window.TotalMilliseconds}";
        var currentKey = $"rate:{clientId}:{now}";

        var previous = await _db.StringGetAsync(previousKey);
        var current = await _db.StringGetAsync(currentKey);

        var prevCount = previous.HasValue ? (int)previous : 0;
        var currCount = current.HasValue ? (int)current : 0;

        var overlap = 1 - (now % (long)window.TotalMilliseconds) / (double)window.TotalMilliseconds;
        var estimatedCount = currCount + (int)(prevCount * overlap);

        if (estimatedCount >= limit)
        {
            return false;
        }

        await _db.StringIncrementAsync(currentKey);
        await _db.KeyExpireAsync(currentKey, window);
        return true;
    }
}

const Redis = require('ioredis');
const redis = new Redis();

async function isAllowed(clientId, limit, windowMs) {
  const now = Date.now();
  const prevKey = `rate:${clientId}:${now - windowMs}`;
  const currKey = `rate:${clientId}:${now}`;

  const [prev, curr] = await Promise.all([
    redis.get(prevKey),
    redis.get(currKey)
  ]);

  const prevCount = parseInt(prev || '0', 10);
  const currCount = parseInt(curr || '0', 10);

  const overlap = 1 - (now % windowMs) / windowMs;
  const estimated = currCount + Math.floor(prevCount * overlap);

  if (estimated >= limit) {
    return false;
  }

  await redis.set(currKey, currCount + 1, 'PX', windowMs);
  return true;
}
